package com.lue.erp.profits;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.lue.erp.auth.AuthUser;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.math.BigDecimal;

/** Settlement cash and explicit fee/adjustment fields remain separate from order sales revenue. */
@Service
public class SettlementImportService {
    private static final Map<String,String> HEADERS=Map.ofEntries(
        Map.entry("店铺标识","shop_identifier"),Map.entry("平台账单号","platform_bill_no"),Map.entry("平台结算明细号","platform_line_no"),Map.entry("平台明细号","platform_line_no"),Map.entry("平台订单号","platform_order_no"),Map.entry("订单明细号","platform_order_line_no"),Map.entry("平台 SKU","platform_sku"),Map.entry("平台SKU","platform_sku"),Map.entry("订单模式","order_mode"),Map.entry("结算日期","settlement_date"),Map.entry("平台费用","platform_fee"),Map.entry("平台费用（元）","platform_fee"),Map.entry("结算金额","settlement_amount"),Map.entry("结算金额（元）","settlement_amount"),Map.entry("调整类型","adjustment_type"),Map.entry("调整金额","adjustment_amount"),Map.entry("调整金额（元）","adjustment_amount"),Map.entry("最终结算","settlement_complete"));
    private final JdbcTemplate db;private final ObjectMapper json;private final ProfitMatchService matching;
    @Value("${lue.import.storage-dir:./data/imports}") private String storageDir;
    public SettlementImportService(JdbcTemplate db,ObjectMapper json,ProfitMatchService matching){this.db=db;this.json=json;this.matching=matching;}

    public Map<String,Object> preview(MultipartFile file){List<Row> rows=parse(file);List<Map<String,Object>> sample=new ArrayList<>();for(Row r:rows.stream().limit(100).toList()){Map<String,Object> row=new LinkedHashMap<>(r.raw);row.put("sourceRow",r.number);row.put("issue",previewIssue(r.raw));sample.add(row);}return Map.of("rows",rows.size(),"sample",sample,"issues",rows.stream().filter(r->previewIssue(r.raw)!=null).count());}

    @Transactional
    public Map<String,Object> upload(MultipartFile file,AuthUser actor){
        List<Row> rows=parse(file);String fileHash=hash(bytes(file));
        Map<String,Object> prior=db.query("SELECT id,batch_no batchNo FROM import_batches WHERE import_type='settlement' AND file_sha256=? AND status IN ('SUCCESS','PARTIAL_SUCCESS') AND is_deleted=FALSE ORDER BY id DESC LIMIT 1",rs->rs.next()?Map.of("id",rs.getLong(1),"batchNo",rs.getString(2)):null,fileHash);
        if(prior!=null)return Map.of("batchNo",prior.get("batchNo"),"rows",rows.size(),"duplicate",true,"matched",0,"pending",0,"dateFrom","","dateTo","");
        LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));db.update("INSERT INTO import_batch_sequences(sequence_date,sequence_value) VALUES (?,1) ON DUPLICATE KEY UPDATE sequence_value=sequence_value+1",today);long seq=db.queryForObject("SELECT sequence_value FROM import_batch_sequences WHERE sequence_date=? FOR UPDATE",Long.class,today);String batchNo="IM"+today.format(DateTimeFormatter.BASIC_ISO_DATE)+String.format(Locale.ROOT,"%08d",seq);
        String original=Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"settlement.xlsx")).getFileName().toString();Path stored=store(batchNo,original,file);
        db.update("INSERT INTO import_batches(batch_no,import_type,original_filename,stored_file_path,file_sha256,status,total_rows,created_by) VALUES (?,'settlement',?,?,?,'VALIDATING',?,?)",batchNo,original,stored.toString(),fileHash,rows.size(),actor.id());long batch=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);
        int valid=0,matched=0,pending=0,duplicates=0;Set<LocalDate> dates=new TreeSet<>();
        for(Row row:rows){Map<String,String> raw=row.raw;String issue=precheck(raw);Long shop=null,sku=null;String shopCode=raw.getOrDefault("shop_identifier","");String platformSku=raw.getOrDefault("platform_sku","");String orderMode=raw.getOrDefault("order_mode","").toUpperCase(Locale.ROOT);
            if(issue==null){shop=db.query("SELECT id FROM shops WHERE shop_identifier=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,shopCode);if(shop==null)issue="店铺不存在或未启用";}
            if(issue==null){Map<String,Object> mapping=db.query("SELECT sku_id skuId,default_order_mode defaultMode FROM shop_sku_mappings WHERE shop_id=? AND platform_sku=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?Map.of("skuId",rs.getLong(1),"defaultMode",rs.getString(2)):null,shop,platformSku);if(mapping==null)issue="平台 SKU 无有效内部映射";else{sku=((Number)mapping.get("skuId")).longValue();if(orderMode.isBlank())orderMode=Objects.toString(mapping.get("defaultMode"),"");}}
            if(issue==null&&!Set.of("JIT","WAREHOUSE").contains(orderMode))issue="订单模式未映射";
            LocalDate settled=null;BigDecimal fee=null,cash=null,adjustment=null;
            if(issue==null){try{settled=LocalDate.parse(raw.get("settlement_date"));fee=money(raw.get("platform_fee"),false);cash=money(raw.get("settlement_amount"),true);adjustment=blank(raw.get("adjustment_amount"))==null?null:money(raw.get("adjustment_amount"),false);}catch(Exception e){issue="结算日期或金额格式无效";}}
            String rawJson=jsonText(raw);String normalized=jsonText(Map.of("shopIdentifier",shopCode,"platformSku",platformSku,"platformOrderNo",raw.getOrDefault("platform_order_no",""),"platformBillNo",raw.getOrDefault("platform_bill_no",""),"platformLineNo",raw.getOrDefault("platform_line_no",""),"orderLineNo",raw.getOrDefault("platform_order_line_no","")));
            db.update("INSERT INTO raw_import_rows(batch_id,source_row_number,raw_data,normalized_data,validation_errors,row_status) VALUES (?,?,CAST(? AS JSON),CAST(? AS JSON),CAST(? AS JSON),?)",batch,row.number,rawJson,normalized,issue==null?"[]":jsonText(List.of(issue)),issue==null?"VALID":"ERROR");long rawId=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);
            if(issue!=null){exception("SETTLEMENT_IMPORT_UNMAPPED",shop,platformSku,"第 "+row.number+" 行结算字段待映射："+issue,rawId);pending++;continue;}
            String bill=blank(raw.get("platform_bill_no")),line=blank(raw.get("platform_line_no"));String fingerprint=bill==null||line==null?hash((fileHash+"|"+row.number).getBytes(java.nio.charset.StandardCharsets.UTF_8)):hash((shopCode+"|"+bill+"|"+line).getBytes(java.nio.charset.StandardCharsets.UTF_8));
            Map<String,Object> existing=db.query("SELECT id,settlement_date settlementDate,platform_fee fee,settlement_amount cash,adjustment_type adjustmentType,adjustment_amount adjustmentAmount,settlement_complete complete,platform_order_no orderNo,platform_order_line_no orderLineNo,platform_sku platformSku FROM settlement_summaries WHERE source_fingerprint=? AND is_deleted=FALSE FOR UPDATE",rs->rs.next()?Map.ofEntries(Map.entry("id",rs.getLong("id")),Map.entry("settlementDate",Objects.toString(rs.getDate("settlementDate"),"")),Map.entry("fee",rs.getBigDecimal("fee")),Map.entry("cash",Objects.toString(rs.getBigDecimal("cash"),"")),Map.entry("adjustmentType",Objects.toString(rs.getString("adjustmentType"),"")),Map.entry("adjustmentAmount",Objects.toString(rs.getBigDecimal("adjustmentAmount"),"")),Map.entry("complete",rs.getBoolean("complete")),Map.entry("orderNo",Objects.toString(rs.getString("orderNo"),"")),Map.entry("orderLineNo",Objects.toString(rs.getString("orderLineNo"),"")),Map.entry("platformSku",rs.getString("platformSku"))):null,fingerprint);
            String type=Objects.toString(raw.get("adjustment_type"),"").toUpperCase(Locale.ROOT).trim();boolean complete=Set.of("Y","YES","TRUE","1","是").contains(Objects.toString(raw.get("settlement_complete"),"").toUpperCase(Locale.ROOT));
            if(existing!=null){boolean same=Objects.equals(existing.get("settlementDate"),settled.toString())&&((BigDecimal)existing.get("fee")).compareTo(fee)==0&&Objects.equals(existing.get("cash"),Objects.toString(cash,""))&&Objects.equals(existing.get("adjustmentType"),type)&&Objects.equals(existing.get("adjustmentAmount"),Objects.toString(adjustment,""))&&Objects.equals(existing.get("complete"),complete)&&Objects.equals(existing.get("orderNo"),Objects.toString(blank(raw.get("platform_order_no")),""))&&Objects.equals(existing.get("orderLineNo"),Objects.toString(blank(raw.get("platform_order_line_no")),""))&&Objects.equals(existing.get("platformSku"),platformSku);if(same){db.update("UPDATE raw_import_rows SET row_status='IMPORTED',imported_record_id=?,validation_errors=CAST('[\"重复结算明细，未重复核销\"]' AS JSON) WHERE id=?",existing.get("id"),rawId);duplicates++;}else{String reason="同一账单及明细号的结算内容与已导入记录冲突，请人工核对";db.update("UPDATE raw_import_rows SET row_status='ERROR',validation_errors=CAST(? AS JSON) WHERE id=?",jsonText(List.of(reason)),rawId);exception("SETTLEMENT_IMPORT_CONFLICT",shop,platformSku,reason,rawId);pending++;}continue;}
            db.update("INSERT INTO settlement_summaries(import_batch_id,source_row_number,shop_id,platform_order_no,platform_bill_no,platform_line_no,platform_order_line_no,platform_sku,sku_id,order_mode,settlement_date,platform_fee,settlement_amount,adjustment_type,adjustment_amount,settlement_complete,source_fingerprint) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",batch,row.number,shop,blank(raw.get("platform_order_no")),bill,line,blank(raw.get("platform_order_line_no")),platformSku,sku,orderMode,settled,fee,cash,blank(type),adjustment,complete,fingerprint);
            long settlement=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);db.update("UPDATE raw_import_rows SET row_status='IMPORTED',imported_record_id=? WHERE id=?",settlement,rawId);valid++;
            if(bill==null||line==null){String reason="缺少稳定平台账单号或结算明细号，不能保证跨文件防重";db.update("UPDATE settlement_summaries SET match_status='UNMAPPED',match_reason=? WHERE id=?",reason,settlement);matching.settlementIssue(settlement,shop,platformSku,reason);pending++;continue;}
            LocalDate orderDay=matching.matchSettlement(settlement);if(orderDay==null)pending++;else{matched++;dates.add(orderDay);}
        }
        db.update("UPDATE import_batches SET status=?,valid_rows=?,error_rows=?,imported_rows=? WHERE id=?",pending>0?"PARTIAL_SUCCESS":"SUCCESS",valid,rows.size()-valid,valid,batch);
        Map<String,Object> result=new LinkedHashMap<>();result.put("batchNo",batchNo);result.put("rows",rows.size());result.put("matched",matched);result.put("pending",pending);result.put("duplicates",duplicates);result.put("duplicate",false);result.put("dateFrom",dates.isEmpty()?"":dates.iterator().next().toString());result.put("dateTo",dates.isEmpty()?"":((TreeSet<LocalDate>)dates).last().toString());return result;
    }

    private List<Row> parse(MultipartFile file){if(file==null||file.isEmpty()||!Objects.requireNonNullElse(file.getOriginalFilename(),"").toLowerCase(Locale.ROOT).endsWith(".xlsx"))throw new IllegalArgumentException("请选择 .xlsx 结算文件");if(file.getSize()>50L*1024*1024)throw new IllegalArgumentException("文件超过 50 MB");try(XSSFWorkbook workbook=new XSSFWorkbook(file.getInputStream())){Sheet sheet=workbook.getSheetAt(0);DataFormatter fmt=new DataFormatter(Locale.ROOT);org.apache.poi.ss.usermodel.Row head=sheet.getRow(0);if(head==null)throw new IllegalArgumentException("缺少表头");Map<String,Integer> columns=new LinkedHashMap<>();for(int i=0;i<head.getLastCellNum();i++){String label=fmt.formatCellValue(head.getCell(i)).trim();if(!label.isBlank()&&columns.putIfAbsent(HEADERS.getOrDefault(label,label),i)!=null)throw new IllegalArgumentException("结算表头重复："+label);}for(String required:List.of("shop_identifier","platform_sku","settlement_date"))if(!columns.containsKey(required))throw new IllegalArgumentException("缺少必填表头："+required);List<Row> rows=new ArrayList<>();for(int n=1;n<=sheet.getLastRowNum();n++){org.apache.poi.ss.usermodel.Row source=sheet.getRow(n);if(source==null)continue;Map<String,String> raw=new LinkedHashMap<>();for(var col:columns.entrySet())raw.put(col.getKey(),fmt.formatCellValue(source.getCell(col.getValue())).trim());if(raw.values().stream().allMatch(String::isBlank)||raw.getOrDefault("shop_identifier","").startsWith("替换为"))continue;rows.add(new Row(n+1,raw));if(rows.size()>20000)throw new IllegalArgumentException("单文件最多 20,000 行");}if(rows.isEmpty())throw new IllegalArgumentException("结算文件没有数据行");return rows;}catch(java.io.IOException e){throw new IllegalArgumentException("结算文件读取失败",e);}}
    private String precheck(Map<String,String> row){if(row.getOrDefault("shop_identifier","").isBlank())return "店铺标识缺失";if(row.getOrDefault("platform_sku","").isBlank())return "平台 SKU 缺失";if(row.getOrDefault("settlement_date","").isBlank())return "结算日期缺失";return null;}
    private String previewIssue(Map<String,String> row){String issue=precheck(row);if(issue!=null)return issue;if(blank(row.get("platform_bill_no"))==null||blank(row.get("platform_line_no"))==null)return "缺少稳定账单/明细标识，待映射";if(blank(row.get("platform_order_no"))==null)return "缺少平台订单号，需人工匹配";if(blank(row.get("adjustment_amount"))!=null&&!Set.of("FEE_DELTA","REFUND_DELTA","OTHER_COST_DELTA").contains(Objects.toString(row.get("adjustment_type"),"").toUpperCase(Locale.ROOT)))return "调整金额类型待映射";return null;}
    private static BigDecimal money(String raw,boolean optional){if(raw==null||raw.isBlank()){if(optional)return BigDecimal.ZERO;throw new IllegalArgumentException("金额缺失");}BigDecimal x=new BigDecimal(raw);if(x.scale()>4||x.precision()-x.scale()>14)throw new IllegalArgumentException("金额超过精度");return x.setScale(4);}
    private void exception(String type,Long shop,String sku,String title,long raw){String no="EX"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);db.update("INSERT INTO exceptions(exception_no,exception_type,shop_id,platform_sku,title,raw_data) VALUES (?,?,?,?,?,JSON_OBJECT('rawImportRowId',?))",no,type,shop,sku,title,raw);}
    private Path store(String batch,String filename,MultipartFile file){try{Path day=Path.of(storageDir).toAbsolutePath().normalize().resolve(LocalDate.now(ZoneId.of("Asia/Shanghai")).toString());Files.createDirectories(day);Path target=day.resolve(batch+"_"+filename).normalize();if(!target.startsWith(day))throw new IllegalArgumentException("文件名无效");Files.write(target,bytes(file),StandardOpenOption.CREATE_NEW);return target;}catch(java.io.IOException e){throw new IllegalArgumentException("原结算文件保存失败",e);}}
    private static byte[] bytes(MultipartFile file){try{return file.getBytes();}catch(java.io.IOException e){throw new IllegalArgumentException("文件读取失败",e);}}
    private String jsonText(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
    private static String hash(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}
    private static String blank(String value){return value==null||value.isBlank()?null:value.trim();}
    private record Row(int number,Map<String,String> raw){}
}
